package com.vandorlabs.neoforge.gear;

import java.util.*;
import net.minecraft.core.*;
import net.minecraft.core.component.DataComponents;
import net.minecraft.nbt.*;
import net.minecraft.server.level.*;
import net.minecraft.world.InteractionHand;
import net.minecraft.world.item.*;
import net.minecraft.world.item.component.CustomData;
import net.minecraft.world.level.GameType;
import net.minecraft.world.level.block.Blocks;
import net.minecraft.world.phys.*;
import net.neoforged.bus.api.SubscribeEvent;
import net.neoforged.fml.common.EventBusSubscriber;
import net.neoforged.neoforge.event.server.ServerStartedEvent;
import net.neoforged.neoforge.event.tick.ServerTickEvent;

/** Real active socket placement and journal adoption, followed by a separate-process moving restart. */
@EventBusSubscriber(modid="vandorlabs")
public final class NativeGearLandingChecks {
    private record Scene(BlockPos root,Direction mount,NativeGearDefinition arm,NativeGearDefinition foot){}
    private static final List<Scene> scenes=new ArrayList<>();private static ServerLevel world;private static Actor actor;private static int stage,ticks,checks;private static boolean running,faulted;
    private static final class Actor extends net.neoforged.neoforge.common.util.FakePlayer {Actor(ServerLevel level){super(level,new com.mojang.authlib.GameProfile(new UUID(0,2211471),"NativeGearLanding"));}}
    private static String phase(){return System.getProperty("vandorlabs.gearLandingPhase","");}
    private static void need(boolean ok,String why){checks++;if(!ok)throw new AssertionError("Landing stage="+stage+" ticks="+ticks+": "+why);}
    private static NativeGearEntity root(Scene scene){var root=NativeGearFormation.at(world,scene.root);need(root!=null&&!root.inert(),"healthy root "+scene);return root;}
    private static void ordinary(Scene scene,ItemStack stack,BlockPos support,Direction face){actor.setPos(scene.root.getX()-4,scene.root.getY()+3,scene.root.getZ()-4);actor.setYRot(0);actor.setItemInHand(InteractionHand.MAIN_HAND,stack);need(actor.gameMode.useItemOn(actor,world,stack,InteractionHand.MAIN_HAND,new BlockHitResult(Vec3.atCenterOf(support).add(Vec3.atLowerCornerOf(face.getNormal()).scale(.5)),face,support,false)).consumesAction(),"Survival item placement "+scene);}
    private static BlockPos socket(NativeGearEntity root){var transform=NativeGearPayload.relativeTransform(root,0,NativeGearPayload.frame(root,1));var home=NativeGearOrientation.vector(root.mount(),new BlockPos(0,-root.assembly().columnHeight(),0));var center=transform.point(home.getX()+.5,home.getY()+.5,home.getZ()+.5);return root.getBlockPos().offset((int)Math.rint(center.x-.5),(int)Math.rint(center.y-.5),(int)Math.rint(center.z-.5));}
    private static NativeGearMechanismTrace.Hit aim(NativeGearEntity root,BlockPos socket){for(var box:root.interactionBoxes(root.progress())){if(!box.intersects(new AABB(socket).inflate(.25)))continue;var target=box.getCenter();for(var side:Direction.values()){var eye=target.add(Vec3.atLowerCornerOf(side.getNormal()).scale(3.5));var look=target.subtract(eye).normalize();actor.setPos(eye.x,eye.y-actor.getEyeHeight(),eye.z);actor.setYRot((float)Math.toDegrees(Math.atan2(-look.x,look.z)));actor.setXRot((float)-Math.toDegrees(Math.asin(look.y)));var hit=NativeGearMechanismTrace.nearest(world,actor.getEyePosition(),actor.getEyePosition().add(actor.getViewVector(1).scale(actor.blockInteractionRange())),NativeGearEntity::progress);if(hit!=null&&hit.owner()==root&&new AABB(socket).inflate(.25).contains(hit.worldPoint())){var obstruction=world.clip(new net.minecraft.world.level.ClipContext(actor.getEyePosition(),actor.getEyePosition().add(actor.getViewVector(1).scale(actor.blockInteractionRange())),net.minecraft.world.level.ClipContext.Block.OUTLINE,net.minecraft.world.level.ClipContext.Fluid.NONE,actor));if(obstruction.getType()!=HitResult.Type.MISS&&actor.getEyePosition().distanceToSqr(obstruction.getLocation())+1e-8<hit.distanceSq()){var member=NativeGearFormation.at(world,obstruction.getBlockPos());if(member==null||member.controllerEntity()!=root)continue;}return hit;}}}throw new AssertionError("No visible active socket "+root.getBlockPos()+" socket="+socket);}
    @SubscribeEvent public static void started(ServerStartedEvent event){if(phase().isEmpty())return;try{world=event.getServer().overworld();actor=new Actor(world);actor.setGameMode(GameType.SURVIVAL);int n=0;for(var mount:Direction.values())for(var arm:new NativeGearDefinition[]{NativeGearDefinition.ROTATING,NativeGearDefinition.LARGE_ROTATING})for(var foot:new NativeGearDefinition[]{NativeGearDefinition.PLATE,NativeGearDefinition.SKI,arm.size==2?NativeGearDefinition.LARGE_WHEEL:NativeGearDefinition.WHEEL})scenes.add(new Scene(new BlockPos(24000+n%12*20,110,24000+n++/12*20),mount,arm,foot));if(phase().equals("crash")||phase().equals("recover")){scenes.clear();scenes.add(new Scene(new BlockPos(24015,110,24015),Direction.EAST,NativeGearDefinition.LARGE_ROTATING,NativeGearDefinition.LARGE_WHEEL));}for(var scene:scenes)for(int x=-1;x<=1;x++)for(int z=-1;z<=1;z++){int cx=(scene.root.getX()>>4)+x,cz=(scene.root.getZ()>>4)+z;world.setChunkForced(cx,cz,true);world.getChunk(cx,cz);}if(phase().equals("recover")){var scene=scenes.getFirst();var root=root(scene);need(root.assembly().kind()==com.vandorlabs.gear.core.GearTopology.FootKind.NONE&&root.progress()==0&&root.blocked(),"startup restored original bare endpoint");var at=socket(root);need(NativeGearComponents.intact(world,at),"startup restored complete native loose wheel");for(var cell:NativeGearComponents.cells(at,NativeGearFormation.at(world,at).componentFrame(),world.getBlockState(at).getValue(NativeGearBlock.FACING))){var tile=NativeGearFormation.at(world,cell);need(tile!=null&&tile.owner()==null&&!tile.getBlockState().getValue(NativeGearBlock.ASSEMBLED),"one unowned original component cell");}need(root.members().size()==2&&root.members().stream().noneMatch(pos->world.getBlockState(pos).getBlock() instanceof NativeGearBlock block&&block.definition().foot()),"bare root owns only its original two arm sections");System.out.println("[vandorlabs][gear-landing] recover PASS checks="+checks+" abruptARMED/nativeLooseWheelExactlyOnce/startupRollback");event.getServer().halt(false);return;}if(phase().equals("read")){stage=10;running=true;for(var scene:scenes){var root=root(scene);root.authorize(actor);need(root.assembly().kind()==scene.foot.footKind()&&root.progress()>0&&root.progress()<1,"saved adopted moving assembly "+scene);need(root.command(true),"restart reversal");}return;}
        for(var scene:scenes){for(int x=-6;x<=6;x++)for(int y=-5;y<=6;y++)for(int z=-6;z<=6;z++)world.setBlock(scene.root.offset(x,y,z),y==-5?Blocks.STONE.defaultBlockState():Blocks.AIR.defaultBlockState(),18);world.setBlock(scene.root.relative(scene.mount.getOpposite()),Blocks.STONE.defaultBlockState(),3);var arms=new ItemStack(NativeGearBindings.ITEMS.get(scene.arm.id),2);var choices=NativeGearSettings.defaults().choices();choices.putBoolean("RotatePayload",true);var data=new CompoundTag();data.put(NativeGearItem.SETTINGS,choices);arms.set(DataComponents.CUSTOM_DATA,CustomData.of(data));for(int p=0;p<2;p++)ordinary(scene,arms,scene.root.relative(scene.mount,p-1),scene.mount);need(arms.isEmpty(),"two arm sections consumed");}running=true;
    }catch(Throwable failure){fail(failure);}}
    @SubscribeEvent public static void tick(ServerTickEvent.Post event){if(!running)return;try{need(++ticks<600,"timeout "+scenes.stream().limit(3).map(s->s+"="+root(s).progress()+"/"+root(s).error()).toList());if(stage==0){for(var scene:scenes)if(!root(scene).controller()||root(scene).assembly().columnHeight()!=2)return;for(var scene:scenes){var root=root(scene);root.authorize(actor);need(root.command(false),"activate empty rotating arm");}stage=1;ticks=0;return;}
        if(stage==1){for(var scene:scenes){var root=root(scene);need(!root.blocked(),"bare stroke "+scene+" "+root.error());if(root.progress()!=0)return;}for(var scene:scenes){var root=root(scene);var at=socket(root);var feet=new ItemStack(NativeGearBindings.ITEMS.get(scene.foot.id),1);actor.setItemInHand(InteractionHand.MAIN_HAND,feet);var hit=aim(root,at);need(new AABB(at).inflate(.25).contains(hit.worldPoint()),"server ray hits visible socket");var packet=new NativeGearMechanismUsePayload(root.getBlockPos(),root.identity(),2);var buf=new net.minecraft.network.RegistryFriendlyByteBuf(io.netty.buffer.Unpooled.buffer(),world.registryAccess());NativeGearMechanismUsePayload.CODEC.encode(buf,packet);need(buf.readableBytes()==25,"bounded root-only interaction packet");var decoded=NativeGearMechanismUsePayload.CODEC.decode(buf);buf.release();need(NativeGearMechanismUsePayload.apply(actor,decoded),"actual active socket interaction "+scene+" hit="+hit);need(feet.isEmpty(),"active foot consumes one kit");var source=NativeGearFormation.at(world,at);need(source!=null&&source.definition()==scene.foot,"active foot is native before journal");source.getPersistentData().putByteArray("LandingOpaque",new byte[128]);root.authorize(actor);}if(phase().equals("crash")){world.getServer().saveEverything(true,true,true);NativeGearJournal.testFault=where->{if(where.equals("after-cell")&&!faulted){faulted=true;var scene=scenes.getFirst();var pos=socket(root(scene));var chunk=world.getChunkSource().getChunkNow(pos.getX()>>4,pos.getZ()>>4);world.getChunkSource().chunkMap.write(new net.minecraft.world.level.ChunkPos(pos),net.minecraft.world.level.chunk.storage.ChunkSerializer.write(world,chunk)).thenCompose(ignored->((com.vandorlabs.neoforge.mixin.NativeRampChunkStorageAccess)(Object)world.getChunkSource().chunkMap).vandorlabs$rampWorker().synchronize(true)).thenRun(()->{System.out.println("[vandorlabs][gear-landing] crash PASS realARMED/partialNativeComponentSave/abruptHalt");System.out.flush();Runtime.getRuntime().halt(0);});}};}stage=2;ticks=0;return;}
        if(stage==2){for(var scene:scenes){var root=root(scene);need(!root.blocked(),"adoption "+scene+" "+root.error());if(root.assembly().kind()!=scene.foot.footKind()||NativeGearJournal.busy(root))return;}for(var scene:scenes){var root=root(scene);need(root.progress()==0,"adoption preserves endpoint");int count=scene.foot==NativeGearDefinition.LARGE_WHEEL?4:1;need(root.assembly().feet().size()==count,"all native component cells adopted");for(var foot:root.assembly().feet()){var at=scene.root.offset(NativeGearOrientation.vector(scene.mount,new BlockPos(foot.x,foot.y,foot.z)));var tile=NativeGearFormation.at(world,at);need(tile!=null&&tile.mount()==scene.mount&&scene.root.equals(tile.owner()),"adopted native owner/frame "+at);if(tile.getBlockState().getValue(NativeGearBlock.PART)==0)need(tile.getPersistentData().getByteArray("LandingOpaque").length==128,"opaque source metadata retained");}root.authorize(actor);need(root.command(true),"adopted return");}stage=3;ticks=0;return;}
        if(stage==3){for(var scene:scenes){var root=root(scene);need(!root.blocked(),"adopted foot return "+scene+" "+root.error());if(root.progress()!=1)return;}for(var scene:scenes){root(scene).authorize(actor);need(root(scene).command(false),"reverse adopted feet");}stage=4;ticks=0;return;}
        if(stage==4){for(var scene:scenes){var root=root(scene);need(!root.blocked(),"adopted motion "+scene+" "+root.error());if(root.progress()>.6)return;need(root.progress()>0,"moving restart phase");}System.out.println("[vandorlabs][gear-landing] write PASS cases="+scenes.size()+" checks="+checks+" realSurvivalSocketPacket/asyncADOPT/nativeComponentFrame/opaqueMetadata/return/reversal/movingSave");running=false;event.getServer().halt(false);return;}
        if(stage==10){for(var scene:scenes){var root=root(scene);need(!root.blocked(),"restart adopted motion "+scene+" "+root.error());if(root.progress()!=1)return;for(var foot:root.assembly().feet()){var at=scene.root.offset(NativeGearOrientation.vector(scene.mount,new BlockPos(foot.x,foot.y,foot.z)));var tile=NativeGearFormation.at(world,at);need(tile!=null&&scene.root.equals(tile.owner())&&tile.mount()==scene.mount,"restart exact native owner/frame");}}System.out.println("[vandorlabs][gear-landing] read PASS cases="+scenes.size()+" checks="+checks+" movingRestart/reversal/nativeFootOwnership");running=false;event.getServer().halt(false);}
    }catch(Throwable failure){fail(failure);}}
    private static void fail(Throwable failure){running=false;failure.printStackTrace();System.out.println("[vandorlabs][gear-landing] "+phase()+" FAIL "+failure);if(world!=null)world.getServer().halt(false);}
}
